def max_profit(prices: List[int], fee: int) -> int:
    if not prices:
        return 0

    n = len(prices)
    if n == 1:
        return 0

    max_profit = 0
    min_price = prices[0] + fee

    for i in range(1, n):
        if prices[i] + fee < min_price:
            min_price = prices[i] + fee
