def calculateSpan(price):
    n = len(price)
    if n == 0:
        return []

    span = [1] * n
    stack = []

    for i in range(1, n):
        while stack and price[stack[-1]] <= price[i]:
            stack.pop()
        if stack:
            span[i] = i - stack[-1]
        else:
            span[i] = i + 1
        stack.append(i)

    return span
