# Let's start by implementing the max_common_substring function using dynamic programming.
# We'll create a 2D array to store the lengths of the longest common suffixes of substrings.
# This approach ensures we efficiently compute the maximum length of the common substring.

def max_common_substring(master: str, slave: str) -> int:
    # Lengths of the input strings
    m, n = len(master), len(slave)

    # Create a 2D array to store lengths of the longest common suffixes
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Variable to store the length of the maximum common substring
    max_length = 0

    # Build the dp array
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if master[i - 1] == slave[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                max_length = max(max_length, dp[i][j])
            else:
                dp[i][j] = 0

    return max_length

