    if requested_book in book_list:
        return "The book '{}' is available.".format(requested_book)

    # Check for partial matches
    suggestions = [book for book in book_list if requested_book in book]

    if suggestions:
        return "The book '{}' is not available. Did you mean: {}?".format(requested_book, ', '.join(suggestions))

    # No matches
    return "The book '{}' is not available, and no similar titles were found.".format(requested_book)
