def minDistance(S, T):
    m, n = len(S), len(T)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # If S is empty, all characters in T must be inserted
            elif j == 0:
                dp[i][j] = i  # If T is empty, all characters in S must be deleted
            elif S[i - 1] == T[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # Characters match, no operation needed
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])  # Choose the minimum operation
    return dp[m][n]

