```python
import json

def extract_json_objects(input_string):
    json_objects = []
    start = 0

    while start < len(input_string):
        try:
            json_object, end = json.loads(input_string[start:], return_pos=True)
            json_objects.append(json_object)
            start = end
        except json.JSONDecodeError:
            start += 1

    return json_objects
