def can_form_palindrome(s):
    s = s.lower()
    s = ''.join(char for char in s if char.isalnum())
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    odd_count = 0
    for count in char_count.values():
