def prime_factors(n: int) -> list:
    # Initialize a list to store prime factors
    factors = []

    # Handle edge case where n is 1
    if n == 1:
        return factors

    # Divide n by 2 until it's odd
    while n % 2 == 0:
        factors.append(2)
        n //= 2

    # Check for odd factors from 3 onwards
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i

    # If n is a prime number greater than 2
    if n > 2:
        factors.append(n)

    return factors
