def multiply_strings(num1: str, num2: str) -> str:
    if num1 == "0" or num2 == "0":
        return "0"

    result = [0] * (len(num1) + len(num2))
    for i in range(len(num1) - 1, -1, -1):
        carry = 0
        for j in range(len(num2) - 1, -1, -1):
            product = (ord(num1[i]) - ord('0')) * (ord(num2[j]) - ord('0')) + carry + result[i + j + 1]
            carry = product // 10
            result[i + j + 1] = product % 10

        result[i] += carry

    while result[0] == 0:
        result.pop(0)

