def firstUniqChar(s):
    # Create a dictionary to store the first index and the count of each character
    char_counts = {}
    for i, char in enumerate(s):
        if char in char_counts:
            char_counts[char][0] = i
            char_counts[char][1] += 1
        else:
            char_counts[char] = [i, 1]

    # Iterate over the dictionary to find the first character with a count of 1
    for char, (index, count) in char_counts.items():
        if count == 1:
            return index

    return -1
