def cumulative_except_self(numbers):
    n = len(numbers)
    if n == 0:
        return []

    left_cumulative = [0] * n
    right_cumulative = [0] * n
    result = [0] * n

    left_cumulative[0] = numbers[0]
    for i in range(1, n):
        left_cumulative[i] = left_cumulative[i - 1] + numbers[i]

    right_cumulative[n - 1] = numbers[n - 1]
    for i in range(n - 2, -1, -1):
        right_cumulative[i] = right_cumulative[i + 1] + numbers[i]

    for i in range(n):
        if i == 0:
            result[i] = right_cumulative[i + 1]
        elif i == n - 1:
            result[i] = left_cumulative[i - 1]
        else:
            result[i] = left_cumulative[i - 1] + right_cumulative[i + 1]

    return result
