```python
def can_form_palindrome(s: str) -> bool:
    # Step 1: Create a hash map to track the frequency of each character
    char_count = {}

    # Step 2: Populate the hash map with character frequencies
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Step 3: Count the number of characters with odd frequencies
    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    # Step 4: Check if the number of characters with odd frequencies is at most 1
    return odd_count <= 1
```

