import math

def PrimeFactorization(M):
    factors = {}
    # Divide M by 2 until it's odd
    while M % 2 == 0:
        if 2 in factors:
            factors[2] += 1
        else:
            factors[2] = 1
        M = M // 2
    # Check for odd factors from 3 onwards
    for i in range(3, int(math.sqrt(M)) + 1, 2):
        while M % i == 0:
            if i in factors:
                factors[i] += 1
            else:
                factors[i] = 1
            M = M // i
    # If M is a prime number greater than 2
    if M > 2:
        factors[M] = 1
    return factors

