def PrimeFactorization(M):
    # Dictionary to store prime factors and their powers
    factors = {}
    # Start with the smallest prime factor
    divisor = 2
    # Continue dividing and factoring until M is reduced to 1
    while M > 1:
        power = 0
        # If M is divisible by the current divisor, divide M by divisor and increase power
        while M % divisor == 0:
            M //= divisor
            power += 1
        # If the power is greater than 0, add the divisor and its power to the factors dictionary
        if power > 0:
            factors[divisor] = power
        # Move to the next potential divisor
        divisor += 1
        # Optimization: After 2, all factors can be checked from 3 onwards in increments of 2 (since even numbers other than 2 are not prime)
        if divisor * divisor > M:
            if M > 1:
                factors[M] = 1
            break
    return factors

