    prime_factors = {}
    # Check for number of 2s in M
    while M % 2 == 0:
        if 2 not in prime_factors:
            prime_factors[2] = 0
        prime_factors[2] += 1
        M //= 2

    # Check for other primes
    factor = 3
    while factor * factor <= M:
        while M % factor == 0:
            if factor not in prime_factors:
                prime_factors[factor] = 0
            prime_factors[factor] += 1
            M //= factor
        factor += 2

    # If M is a prime number greater than 2
    if M > 2:
        prime_factors[M] = 1

