def transform_point(matrix: [[float, float], [float, float]], point: (float, float)) -> (float, float):
    # Check if the matrix is a 2x2 list
    if not isinstance(matrix, list) or len(matrix) != 2:
        raise Exception("Invalid transformation matrix")

    # Check if the matrix contains only float elements
    for row in matrix:
        if not isinstance(row, list) or len(row) != 2 or not all(isinstance(item, float) for item in row):
            raise Exception("Invalid transformation matrix")

    # Check if the point is a tuple of two floats
    if not isinstance(point, tuple) or len(point) != 2 or not all(isinstance(item, float) for item in point):
        raise Exception("Invalid point coordinates")

    # Apply the transformation matrix to the point
    x_new = matrix[0][0] * point[0] + matrix[0][1] * point[1]
    y_new = matrix[1][0] * point[0] + matrix[1][1] * point[1]

    return (x_new, y_new)
