def compress_string(s: str) -> str:
    if not isinstance(s, str) or not s:
        raise TypeError("input must be a non-empty string")

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.extend([s[i - 1], str(count)])
            count = 1

    compressed.extend([s[-1], str(count)])

    return ''.join(compressed if len(compressed) < len(s) else s)
