def ternary_search(left: int, right: int, key: int, arr: List[int]) -> int:
    while left <= right:
        if left == right:
            if arr[left] == key:
                return left
            return -1

        third = left + (right - left) // 3
        secondthird = right - (right - left) // 3

        if key == arr[third]:
            return third
        elif key == arr[secondthird]:
            return secondthird
        elif key < arr[third]:
            right = third - 1
        elif key > arr[secondthird]:
            left = secondthird + 1
        else:
            left = third + 1
            right = secondthird - 1

