def left_rotate(y):
    x = y.right
    T2 = x.left

    x.left = y
    y.right = T2

    y.size = 1 + size(y.left) + size(y.right)
    x.size = 1 + size(x.left) + size(x.right)

    return x

def right_rotate(x):
    y = x.left
    T2 = y.right

    y.right = x
    x.left = T2

    x.size = 1 + size(x.left) + size(x.right)
    y.size = 1 + size(y.left) + size(y.right)

    return y

def get_height(node):
    if node is None:
