def parse_log_entries(logs: List[str]) -> Dict[str, Any]:
    summary = {
        'total_requests': 0,
        'methods': {},
        'average_response_time': 0.0,
        'status_codes': {}
    }

    total_response_time = 0
    num_requests = 0

    for log_entry in logs:
        parts = log_entry.split()
        if len(parts) != 4:
            continue

        method, url, status_code, response_time = parts
        response_time = int(response_time)

        # Update totals
        summary['total_requests'] += 1
        summary['total_response_time'] += response_time
        num_requests += 1

        # Update methods
        if method in summary['methods']:
            summary['methods'][method] += 1
        else:
            summary['methods'][method] = 1

        # Update status codes
        if status_code in summary['status_codes']:
            summary['status_codes'][status_code] += 1
        else:
