def hasPath(grid):
    m, n = len(grid), len(grid[0])

    # Helper function to perform DFS
    def dfs(x, y):
        # Check if the current position is out of bounds or an obstacle
        if x < 0 or x >= m or y < 0 or y >= n or grid[x][y] == '#' or grid[x][y] == 'V':
            return False
        # Check if the current position is the goal
        if grid[x][y] == 'G':
            return True
        # Mark the current position as visited
        grid[x][y] = 'V'
        # Explore all four possible directions
        return dfs(x + 1, y) or dfs(x - 1, y) or dfs(x, y + 1) or dfs(x, y - 1)

    # Find the starting position
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 'P':
                start = (i, j)
                break

    # Perform DFS from the starting position
    return "Yes" if dfs(start[0], start[1]) else "No"
