def max_sweetness(candies, k):
    def can_select(n, k):
        segments = 0
        current_sweetness = 0
        for candy in candies:
            if current_sweetness + candy >= n:
                segments += 1
                current_sweetness = candy
            else:
                current_sweetness += candy
        if segments >= k + 1:
            return True
        return False

    left, right = 0, sum(candies) + 1
    result = 0
    while left < right:
        mid = (left + right) // 2
        if can_select(mid, k):
            result = mid
            left = mid + 1
        else:
            right = mid
    return result

