def common_elements(arr1: list[int], arr2: list[int]) -> list[int]:
    """
    Returns a sorted array of the common elements between two input sorted arrays.
    """
    # Initialize result list
    result = []
    # Create iterators for both arrays
    iter1, iter2 = iter(arr1), iter(arr2)
    next1, next2 = next(iter1, None), next(iter2, None)

    # Use set to avoid duplicates
    common = set()

    # Traverse both lists and collect common elements
    while next1 is not None and next2 is not None:
        if next1 < next2:
            next1 = next(iter1, None)
        elif next1 > next2:
            next2 = next(iter2, None)
        else:
            common.add(next1)
            next1 = next(iter1, None)
            next2 = next(iter2, None)

    # Convert the result set to a sorted list before returning
    return sorted(common)
```

