def custom_sort(lst: List[int], cmp: Callable[[int, int], int]) -> List[int]:
    sorted_list = lst[:]
    n = len(sorted_list)
    for i in range(n):
        for j in range(0, n-i-1):
            if cmp(sorted_list[j], sorted_list[j+1]) > 0:
                sorted_list[j], sorted_list[j+1] = sorted_list[j+1], sorted_list[j]
