def search_rotated_array(arr: list[int], target: int) -> int:
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return mid

        # Check if the left part is sorted
        if arr[left] <= arr[mid]:
            # Check if the target is in the left part
            if arr[left] <= target <= arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            # Check if the target is in the right part
            if arr[mid] <= target <= arr[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

