def find_frequent_purchases(data: list[tuple[str, str]]) -> dict[str, str]:
    """
    Identify the most frequently purchased product per customer.

    Args:
    - data (list[tuple[str, str]]): A list of tuples where each tuple contains a customer ID and a product ID representing a purchase.

    Returns:
    - dict[str, str]: A dictionary where keys are customer IDs and the values are the most frequently purchased product IDs.
    """
    purchase_counts = {}
    max_purchases = {}

    for customer, product in data:
        if customer not in purchase_counts:
            purchase_counts[customer] = {product: 0}
        if product not in purchase_counts[customer]:
            purchase_counts[customer][product] = 0
        purchase_counts[customer][product] += 1

        if customer not in max_purchases or purchase_counts[customer][product] > max_purchases[customer]:
            max_purchases[customer] = purchase_counts[customer][product]

    result = {}
    for customer, counts in purchase_counts.items():
        for product, count in counts.items():
            if count == max_purchases[customer]:
                result[customer] = product
                break

    return result
