def reachable_airports(flight_routes, starting_airport):
    from collections import defaultdict, deque

    # Build a graph using adjacency list
    graph = defaultdict(list)
    for airport1, airport2 in flight_routes:
        graph[airport1].append(airport2)
        graph[airport2].append(airport1)

    # Initialize the queue and visited set
    queue = deque([starting_airport])
    visited = set()

    # Perform BFS to find all reachable airports
    while queue:
        current_airport = queue.popleft()
        if current_airport not in visited:
            visited.add(current_airport)
            for next_airport in graph[current_airport]:
                if next_airport not in visited:
                    queue.append(next_airport)

    # Return the list of visited airports, excluding the starting airport
    return list(visited - {starting_airport})

