def shortest_paths(num_nodes, connections):
    # Initialize a dictonary to store the connections with weights
    graph = {node: [] for node in range(num_nodes)}
    for u, v, w in connections:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Initialize a list to store the shortest path lengths
    shortest_path_lengths = [float('inf')] * num_nodes
    shortest_path_lengths[0] = 0

    # Initialize a priority queue for Dijkstra's algorithm
    priority_queue = [(0, 0)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > shortest_path_lengths[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < shortest_path_lengths[neighbor]:
                shortest_path_lengths[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    # Replace infinity with -1 where no path has been found
    for i in range(num_nodes):
        if shortest_path_lengths[i] == float('inf'):
            shortest_path_lengths[i] = -1

    return shortest_path_lengths

