def compress_image_rle(grid: list[list[int]]) -> list[list[tuple[int, int]]]:
    compressed_grid = []

    for row in grid:
        compressed_row = []
        count = 1

        for i in range(1, len(row)):
            if row[i] == row[i - 1]:
                count += 1
            else:
                compressed_row.append((row[i - 1], count))
                count = 1
        compressed_row.append((row[-1], count))
        compressed_grid.append(compressed_row)

    return compressed_grid
