def balanceBrackets(brackets):
    stack = []
    insertions = 0
    deletions = 0
    i = 0

    while i < len(brackets):
        char = brackets[i]

        if char == '(':
            stack.append(char)
        else:
            # Stack is not empty, means a matching opening bracket exists
            if stack:
                stack.pop()
            # Stack is empty, means there's no matching opening bracket
            else:
                deletions += 1

        i += 1

    # After processing all characters, remaining items in stack are unmatched opening brackets
    insertions += len(stack)

    balanced_str = ''.join(stack)
    for _ in range(insertions):
        balanced_str += '('
    for _ in range(deletions):
        balanced_str = balanced_str[:-1]

    return balanced_str, insertions + deletions

