def min_window_substring(s: str, t: str) -> str:
    from collections import Counter

    if len(t) > len(s):
        return ""
    count_t = Counter(t)
    count_window = {}
    required = len(count_t)
    formed = 0
    left = 0

    min_length = float("inf")
    min_left = 0

    for right, c in enumerate(s):
        if c in count_t:
            count_window[c] = count_window.get(c, 0) + 1
            if count_window[c] == count_t[c]:
                formed += 1

        while left <= right and formed == required:
            if right - left + 1 < min_length:
                min_length = right - left + 1
                min_left = left

            if s[left] in count_t:
                count_window[s[left]] -= 1
                if count_window[s[left]] < count_t[s[left]]:
                    formed -= 1
            left += 1

    return "" if min_length == float("inf") else s[min_left:min_left+min_length]
```

