    def canConvertString(self, s: str, t: str) -> bool:
        # First, check if the lengths of both strings are the same
        if len(s) != len(t):
            return False

        # Create a dictionary to map characters from s to t
        mapping = {}
        # Create a set to keep track of characters we have already mapped
        used = set()

        for char_s, char_t in zip(s, t):
            # If the character is already in the mapping, check if it maps to the same character
            if char_s in mapping:
                if mapping[char_s] != char_t:
                    return False
            else:
                # If the character from t is already used in the mapping, return False
                if char_t in used:
                    return False
                # Otherwise, add the mapping and mark the character from t as used
                mapping[char_s] = char_t
                used.add(char_t)

        # If all characters are valid and uniquely mapped, return True
        return True
