        return x * y

    # Dictionary to map each item type to its corresponding operation function
    operation_map = {
        'A': add,
        'B': subtract,
        'C': multiply,
    }

    # Get the appropriate function based on item type
    operation_function = operation_map.get(item)

    if operation_function is None:
