def merge_dictionaries(dict1, dict2):
    """
    Recursively merges two dictionaries. If the same key exists and both values are dictionaries, 
    it merges them recursively. Otherwise, the value from dict2 overwrites the value from dict1.
    """
    for key, value in dict2.items():
        if key in dict1 and isinstance(dict1[key], dict) and isinstance(value, dict):
            merge_dictionaries(dict1[key], value)
        else:
            dict1[key] = value
    return dict1
