def anagram_difference(str1: str, str2: str) -> int:
    # Create a dictionary to count occurrences of each character in str1
    count_str1 = {}
    for char in str1:
        if char in count_str1:
            count_str1[char] += 1
        else:
            count_str1[char] = 1

    # Create a dictionary to count occurrences of each character in str2
    count_str2 = {}
    for char in str2:
        if char in count_str2:
            count_str2[char] += 1
        else:
            count_str2[char] = 1

    # Calculate the total deletions needed
    deletions = 0
    for key, value in count_str1.items():
        if key in count_str2:
            deletions += abs(value - count_str2[key])
            del count_str2[key]
        else:
            deletions += value
    for key, value in count_str2.items():
        deletions += value

    return deletions
