def first_non_repeating_char_index(s: str) -> int:
    """
    Finds the index of the first non-repeating character in the string.
    If no non-repeating character exists, returns -1.

    :param s: The input string containing lowercase English letters.
    :return: The index of the first non-repeating character, or -1 if none exists.
    """
    char_count = {}
    for i, char in enumerate(s):
        if char in char_count:
            char_count[char][0] += 1
        else:
            char_count[char] = [1, i]

    for char in s:
        if char_count[char][0] == 1:
            return char_count[char][1]
    return -1

