def minBooks(ratings):
    n = len(ratings)
    books = [1] * n

    # Traverse the ratings array from left to right
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            books[i] = books[i - 1] + 1

    # Traverse the ratings array from right to left
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            books[i] = max(books[i], books[i + 1] + 1)

    return sum(books)

