import re
import operator

def evaluateExpression(expression: str) -> float:
    # Remove all whitespace characters from the expression
    expression = re.sub(r'\s', '', expression)

    # Define the precedence of the operators
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    # Define the operators
    ops = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv}

    # Function to apply an operator to the top two elements on the stack
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        values.append(ops[operator](left, right))

    # Function to process the operators and values
    def process(expression):
        values = []
        operators = []
        i = 0
        while i < len(expression):
            if expression[i].isdigit():
                j = i
                while j < len(expression) and expression[j].isdigit():
                    j += 1
                values.append(float(expression[i:j]))
                i = j
            elif expression[i] == '(':
                operators.append(expression[i])
                i += 1
            elif expression[i] == ')':
                while operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Pop the '('
                i += 1
            elif expression[i] in precedence:
                while (operators and operators[-1] in precedence and
                       precedence[operators[-1]] > precedence[expression[i]]):
                    apply_operator(operators, values)
                operators.append(expression[i])
                i += 1
        while operators:
            apply_operator(operators, values)
        return values[0]

    return process(expression)

