def shortest_to_target(s: str, target: str) -> List[int]:
    n = len(s)
    result = [float('inf')] * n

    # Traverse from left to right to find the nearest target to the left
    last_target_index = -1
    for i in range(n):
        if s[i] == target:
            last_target_index = i
        if last_target_index != -1:
            result[i] = min(result[i], i - last_target_index)

    # Traverse from right to left to find the nearest target to the right
    last_target_index = n
    for i in range(n - 1, -1, -1):
        if s[i] == target:
            last_target_index = i
        if last_target_index != n:
            result[i] = min(result[i], last_target_index - i)

    return result
