def rotate_2d_array(matrix, k):
    if not matrix or not matrix[0]:
        return matrix

    num_rows = len(matrix)
    num_cols = len(matrix[0])
    k %= num_cols  # Reduce k if it's greater than the number of columns

    for row in matrix:
        # Rotate each row by k steps
        row[:] = row[-k:] + row[:-k]

    return matrix

