def longest_increasing_subsequence(transactions: list[int]) -> int:
    # If the list is empty or has only one element, return the length as 1
    if not transactions or len(transactions) == 1:
        return 1

    # Initialize the list to store the smallest tail values for increasing subsequences
    tails = []

    for num in transactions:
        # Use binary search to find the position where 'num' fits in the 'tails' list
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid
        # If 'num' is larger than all tails, append it to the end
        if left == len(tails):
            tails.append(num)
        # Otherwise, replace the tail at index 'left' with 'num'
        else:
            tails[left] = num

    # The length of 'tails' is the length of the longest increasing subsequence
    return len(tails)

# Example usage:
transactions = [10, 9, 2, 5, 3, 7, 101, 18]
print(longest_increasing_subsequence(transactions))  # Output: 4
