def compare_file_sets(primary_list, backup_list):
    # Create dictionaries to store the files and their hashes for quick lookup
    primary_dict = {file[0]: file[1] for file in primary_list}
    backup_dict = {file[0]: file[1] for file in backup_list}

    # Initialize lists to store the results
    new_files = []
    deleted_files = []
    modified_files = []

    # Check for new files in primary_list
    for file in primary_dict:
        if file not in backup_dict:
            new_files.append(file)

    # Check for deleted files in backup_list
    for file in backup_dict:
        if file not in primary_dict:
            deleted_files.append(file)

    # Check for modified files
    for file in primary_dict:
        if file in backup_dict and primary_dict[file] != backup_dict[file]:
            modified_files.append(file)

    return new_files, deleted_files, modified_files
