        queue, fresh = deque(), set()
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 1:
                    fresh.add((r,c))
                elif grid[r][c] == 2:
                    queue.append((r, c))
        minutes = 0
        while queue and fresh:
            size = len(queue)
            for _ in range(size):
                r, c = queue.popleft()
                if (r, c) not in fresh:
                    continue
                fresh.remove((r, c))
                minutes = max(minutes, 0)
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    x, y = r + dx, c + dy
                    if x < 0 or x >= rows or y < 0 or y >= cols:
                        continue
                    if grid[x][y] != 1:
                        continue
                    queue.append((x, y))
                    fresh.discard((x, y))
