def find_smallest_missing_positive(nums):
    size = len(nums)
    if 1 not in nums:
        return 1
    if size == 1:
        return 2

    # Replace negative numbers, zeros, and numbers larger than size with 1
    for i in range(size):
        if nums[i] <= 0 or nums[i] > size:
            nums[i] = 1

    # Use index mapping to mark the presence of numbers
    for i in range(size):
        index = abs(nums[i]) - 1
        nums[index] = -abs(nums[index])

    # The first positive index + 1 is the smallest missing positive
    for i in range(size):
        if nums[i] > 0:
            return i + 1

    return size + 1

