def min_removal_to_balance_parentheses(s: str) -> str:
    """
    Converts a string with unbalanced parentheses into a balanced string by removing the minimum number of invalid parentheses.

    Parameters:
    s (str): The input string consisting only of '(' and ')'.

    Returns:
    str: A new balanced string with the same valid parentheses as the input.
    """

    def is_valid(s: str) -> bool:
        """Check if a string with parentheses is valid."""
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
                if balance < 0:
                    return False
        return balance == 0

    stack = []
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')' and stack:
            stack.pop()

    # If already balanced, no need to modify the string
    if len(stack) == 0:
        return s

    result = ""
    last_removed = -1
    for current in range(len(s)):
        if current in stack and s[current] == '(':
            # Skip the unmatched '('
            continue
        elif current not in stack:
            if last_removed + 1 != current:
                result += s[last_removed + 1:current]
            last_removed = current

    return result + s[last_removed + 1:]

