```python
def find_valley_points(grid: list[list[int]]) -> list[tuple[int, int]]:
    if not grid or not grid[0]:
        return []

    num_rows = len(grid)
    num_cols = len(grid[0])
    valley_points = []

    for i in range(num_rows):
        for j in range(num_cols):
            is_valley = True
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < num_rows and 0 <= nj < num_cols and grid[i][j] >= grid[ni][nj]:
                    is_valley = False
                    break
            if is_valley:
                valley_points.append((i, j))

    return valley_points
