class Graph:
    def __init__(self, vertex_count: int):
        # Initialize an adjacency list for the graph
        self.adj_list = [[] for _ in range(vertex_count)]

    def add_edge(self, source: int, target: int):
        # Add a directed edge from source to target
        self.adj_list[source].append(target)

    def dfs(self, source: int, visited: List[bool], target: int) -> bool:
        # Helper function to perform DFS and check for path
        if source == target:
            return True
        visited[source] = True
        for neighbor in self.adj_list[source]:
            if not visited[neighbor]:
                if self.dfs(neighbor, visited, target):
                    return True
        return False

def is_reachable(vertex_count: int, edges: List[Tuple[int, int]], source: int, target: int) -> bool:
    # Create an instance of Graph
    graph = Graph(vertex_count)
    # Add edges to the graph
    for edge in edges:
        graph.add_edge(edge[0], edge[1])
    # Initialize visited array
    visited = [False] * vertex_count
    # Perform DFS from the source to check if target is reachable
    return graph.dfs(source, visited, target)

