def smallest_missing_positive(nums: List[int]) -> int:
    n = len(nums)
    contains_one = False

    # Check if there's a 1 in the array
    for num in nums:
        if num == 1:
            contains_one = True
            break
    if not contains_one:
        return 1

    # Replace negative numbers, zeros, and numbers larger than n with 1
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = 1

    # Use index mapping to mark the presence of numbers
    for num in nums:
        index = abs(num) - 1
        nums[index] = -abs(nums[index])

    # The first positive index + 1 indicates the smallest missing positive
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    return n + 1
