To solve this problem, we can use the Breadth-First Search (BFS) algorithm. BFS is well-suited for finding the shortest path in an unweighted grid. Here's a step-by-step implementation of the solution:

1. Initialize a queue to perform BFS and a set to keep track of visited cells.
2. Start from the top-left corner of the grid and mark it as visited.
3. Use vectors to store the directions for moving up, down, left, and right.
4. While the queue is not empty, dequeue a cell and check all four possible directions.
5. If a target cell (value 2) is reached, return the number of steps taken.
6. If an empty cell (value 0) is found, enqueue it and mark it as visited.
7. If no path to any target cell is found, return -1.

Here's the complete C++ implementation:

```cpp
class Solution {
public:
    int shortestPath(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        if (m == 0 || n == 0 || grid[0][0] == 1) return -1;

        vector<pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        queue<pair<int, int>> q;
        set<pair<int, int>> visited;

        q.push({0, 0});
        visited.insert({0, 0});

        int steps = 0;

        while (!q.empty()) {
            int size = q.size();
            while (size--) {
                auto cell = q.front();
                q.pop();

                if (grid[cell.first][cell.second] == 2) {
                    return steps;
                }

                for (auto& dir : directions) {
                    int x = cell.first + dir.first;
                    int y = cell.second + dir.second;

                    if (x < 0 || x >= m || y < 0 || y >= n || visited.count({x, y}) || grid[x][y] == 1) continue;

                    q.push({x, y});
                    visited.insert({x, y});
                }
            }
            steps++;
        }

        return -1;
    }
};
```

