def shortestPath(grid):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    m, n = len(grid), len(grid[0])
    start = None
    targets = []

    # Find start and targets
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2:
                targets.append((i, j))
            elif grid[i][j] == 0:
                start = (i, j)

    if not start or not targets:
        return -1

    # BFS to find the shortest path
    queue = deque([(start, 0)])
    visited = set()
    visited.add(start)

    while queue:
        (x, y), steps = queue.popleft()

        if (x, y) in targets:
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 0 and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append(((nx, ny), steps + 1))

    return -1

