def longest_substring_with_two_distinct(s: str) -> int:
    if not s:
        return 0

    # 使用字典来记录字符的索引
    char_index = {}
    max_length = 0
    start = 0

    for end in range(len(s)):
        char = s[end]
        if char in char_index:
            # 更新字符的索引
            char_index[char] = end
        else:
            # 如果字典中已经有两个不同的字符
