def strong_password(n, password):
    numbers = "0123456789"
    lower_case = "abcdefghijklmnopqrstuvwxyz"
    upper_case = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    special_characters = "!@#$%^&*()-+"

    # Set to keep track of the required character types
    required = set()

    # Check each character in the password
    for char in password:
        if char in numbers:
            required.discard('n')
        elif char in lower_case:
            required.discard('l')
        elif char in upper_case:
            required.discard('u')
        elif char in special_characters:
            required.discard('s')

    # If password is already long enough, we just need to add required character types
    if n >= 6:
        return len(required)

    # If password length is less than 6, we need to add enough characters to reach at least 6
    return max(6 - n, len(required))

