def search_in_sorted_matrix(mat: List[List[int]], target: int) -> Tuple[int, int]:
    # Check if the matrix is empty
    if not mat or not mat[0]:
        return (-1, -1)

    # Initialize indices for the top-right corner of the matrix
    row, col = 0, len(mat[0]) - 1

    # Loop until the indices go out of bounds
    while row < len(mat) and col >= 0:
        if mat[row][col] == target:
            return (row, col)
        elif mat[row][col] < target:
            # Move down if the target is greater and in the current row
            row += 1
        else:
            # Move left if the target is smaller and in the current column
            col -= 1

    # Return (-1, -1) if the target is not found
    return (-1, -1)
