import math

def are_collinear(points):
    if len(points) < 2:
        return True  # fewer than 2 points are collinear by definition

    # choose the first point
    x0, y0 = points[0]

    # calculate the angle formed by the line segment joining first point to all other points with the x-axis
    angle_to_first = None
    for x, y in points[1:]:
        if x == x0:
            angle = 90  # vertical line
        else:
            angle = math.degrees(math.atan((y - y0) / (x - x0)))

        if angle_to_first is None:
            angle_to_first = angle
        elif math.isclose(angle, angle_to_first) is False:
            return False

    return True
