from collections import deque

def shortest_path(grid: list[list[int]], start: tuple[int, int], end: tuple[int, int]) -> int:
    if not grid or start == end:
        return -1  # No path required if either grid is empty or start is the end

    rows, cols = len(grid), len(grid[0])
    if start[0] >= rows or start[1] >= cols or end[0] >= rows or end[1] >= cols or grid[start[0]][start[1]] == 1 or grid[end[0]][end[1]] == 1:
        return -1  # Invalid start or end point or cell

    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]  # Right, Down, Up, Left
    visited = set()
    queue = deque([(start, 0)])

    while queue:
        (x, y), steps = queue.popleft()
        if (x, y) == end:
            return steps  # Target found
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 0 and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append(((nx, ny), steps + 1))

    return -1  # No path found
```

