import math

def is_PerfectNumber(n):
    # Check if n is less than 1, since a Perfect Number must be positive
    if n < 1:
        return 0

    # Initialize sum of divisors with 1, since 1 is a proper divisor of all positive integers
    sum_of_divisors = 1

    # Loop to find divisors and add them to sum_of_divisors
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            sum_of_divisors += i
            if i != n // i:  # Check to avoid adding the square root twice if it's a perfect square
                sum_of_divisors += n // i

    # Check if the sum of divisors equals the number
    if sum_of_divisors == n:
        return 1
    else:
        return 0
