def reorganize_books(books: list[tuple[str, int]]) -> list[tuple[str, int]]:
    # Creating a dictionary to count the occurrences of each book
    count = {}
    for title, frequency in books:
        if title in count:
            count[title].append(frequency)
        else:
            count[title] = [frequency]

    # Sorting the books by frequency in descending order
    sorted_books = sorted(books, key=lambda x: (-x[1], book_index(x[0], books)))

