def bubble_sort_descend(arr, n):
    # Base case: if the array is empty or contains a single element, no need to sort
    if n <= 1:
        return arr

    # Perform one pass to bring the largest element to the end of the array
    for i in range(n-1):
        if arr[i] < arr[i+1]:
            arr[i], arr[i+1] = arr[i+1], arr[i]

    # Recursively sort the remaining elements of the array
    return bubble_sort_descend(arr, n-1)

def sort_descend(array):
    # Check if the array is empty or contains a single element
    if len(array) <= 1:
        return array

    # Sort the array using descending order bubble sort
    return bubble_sort_descend(array, len(array))

# Example usage
