def bubble_sort(arr):
    n = len(arr)
    if n <= 1:
        return arr
    for i in range(n):
        # Create a flag to check if any swapping occurs
        swapped = False
        for j in range(0, n-i-1):
            if arr[j] < arr[j+1]:
                # Swap if the element found is less than the next element
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swapped = True
        # If no two elements were swapped by inner loop, then break
        if not swapped:
            break
    return arr

def reverse_bubble_sort(arr):
    n = len(arr)
    if n <= 1:
        return arr
    for i in range(n):
        swapped = False
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:  # Swap if the element found is greater than the next element
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swapped = True
        if not swapped:
            break
    return arr

def main(arr):
    sorted_arr = bubble_sort(arr)
    return reverse_bubble_sort(sorted_arr)

# Example usage:
arr = [64, 34, 25, 12, 22, 11, 90]
sorted_descending = main(arr)
print("Sorted in descending order:", sorted_descending)
