def decode_string(encoded: str) -> str:
    # Helper function to decode a segment of the string enclosed in brackets
    def decode_segment(segment: str) -> str:
        repeat, current = 0, ""
        # Iterate through each character in the segment
        for char in segment:
            if char.isdigit():
                # Build the number for repetitions
                repeat = repeat * 10 + int(char)
            elif char == '[':
                # Recursively decode the inner segment
                inner_segment = decode_segment(encoded[encoded.index('[', len(segment)) + 1:])
                current += repeat * inner_segment
                repeat = 0
            elif char == ']':
                # End of a segment, return the decoded portion
                return current
            else:
                # Single character, concatenate directly
                current += char
        return current

    # Start decoding from the full encoded string
    return decode_segment(encoded)

