import heapq

def find_shortest_paths(start_location: str, city_map: dict) -> dict:
    # Initialize the distance dictionary with infinity for all locations
    distances = {node: float('inf') for node in city_map}
    distances[start_location] = 0

    # Priority queue for Dijkstra's algorithm
    priority_queue = [(0, start_location)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If we've found a shorter path to the current node, ignore this iteration
        if current_distance > distances[current_node]:
            continue

        # Explore each neighbor
        for neighbor, weight in city_map[current_node].items():
            distance = current_distance + weight

            # Only consider this new path if it's better
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

