def min_words_to_form_target(words, target):
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    target_word_chars = list(target)
    words_required = 0

    while target_word_chars:
        found_word = False
        for word in word_count:
            if target_word_chars[:len(word)] == list(word):
                target_word_chars = target_word_chars[len(word):]
                word_count[word] -= 1
                if word_count[word] == 0:
                    del word_count[word]
                found_word = True
                break
        if not found_word:
            return -1
        words_required += 1

    return words_required

