from collections import defaultdict

def min_words_to_form_target(words, target):
    # Create a frequency dictionary for each letter in words
    freq = defaultdict(int)
    for word in words:
        for letter in word:
            freq[letter] += 1

    # Create a frequency dictionary for the target word
    target_freq = defaultdict(int)
    for letter in target:
        target_freq[letter] += 1

    # Check if the target word can be formed by the available letters
    for letter, count in target_freq.items():
        if letter not in freq or count > freq[letter]:
            return -1

    # Helper function to recursively form the target word
    def dfs(index, remaining):
        if index == len(target):
            return 0
        if remaining < 0:
            return float('inf')

        # Try using the current letter or skipping it
        use_current_letter = 1 + dfs(index + 1, remaining - freq[target[index]])
        skip_current_letter = dfs(index + 1, remaining)
        return min(use_current_letter, skip_current_letter)

    # Start the recursive process
    result = dfs(0, sum(target_freq.values()))
    if result == float('inf'):
        return -1
    else:
        return result

# Test the function
