def can_transform_by_swaps(str1: str, str2: str) -> bool:
    # Check if the lengths of the strings are the same
    if len(str1) != len(str2):
        return False

    # If the strings are already the same, return True
    if str1 == str2:
        return True

    # Create a dictionary to store the frequency of each character in str1
    char_count = {}
    for char in str1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check if each character in str2 exists in str1 with the same frequency
    for char in str2:
        if char not in char_count:
            return False
        char_count[char] -= 1
        if char_count[char] < 0:
            return False

    # Check for at most two distinct characters that appear more than once in str1
    distinct_count = 0
    for count in char_count.values():
        if count > 0:
            distinct_count += 1

    return distinct_count <= 2

