from typing import List
import numpy as np

class Solution:
    def uniquePathsWithObstacles(self, obstacleGrid: List[List[int]]) -> int:
        # Convert the obstacle grid to a NumPy array for easier manipulation
        grid = np.array(obstacleGrid)

        # Initialize the number of rows and columns
        m, n = grid.shape

        # Create a 3D NumPy array to store the paths
        paths = np.zeros((m, n, 2), dtype=int)

        # Initialize the starting point
        if grid[0, 0] == 0:
            paths[0, 0, 0] = 1

        # Fill in the first row and first column if there are no obstacles
        for i in range(1, m):
            if grid[i, 0] == 0:
                paths[i, 0, 0] = paths[i-1, 0, 0]

        for j in range(1, n):
            if grid[0, j] == 0:
                paths[0, j, 0] = paths[0, j-1, 0]

        # Fill in the rest of the array based on the number of paths to each cell
        for i in range(1, m):
            for j in range(1, n):
                if grid[i, j] == 0:
                    paths[i, j, 0] = paths[i-1, j, 0] + paths[i, j-1, 0]

        # Return the number of paths through the bottom-right cell
        return paths[m-1, n-1, 0] if grid[m-1, n-1] == 0 else 0
