import functools

# A function to evaluate the expression
def evaluate_expression(expression):
    def operation(op, accumulator, operand):
        if op == '+':
            return accumulator + operand
        elif op == '-':
            return accumulator - operand
        else:
            raise ValueError("Invalid operator")

    # Splitting the expression
    tokens = expression.replace(" ", "").split('+')
    result = functools.reduce(lambda acc, token: operation('-', acc, functools.reduce(lambda acc, ch: int(ch), token[::-1])), tokens[::-1])
    return result

# Wrapping the evaluate_expression function in calculate_expression
def calculate_expression(s: str) -> int:
