import tokenize
import io
import os

def transform_integers_to_hex(file_path: str) -> str:
    with open(file_path, 'rb') as file:
        source_code = file.read()
        tokens = list(tokenize.tokenize(io.BytesIO(source_code).readline))

    transformed_tokens = []
    for token in tokens:
        if token.type == tokenize.NUMBER:
            try:
                num = int(token.string, 0)
            except ValueError:
                continue
            if num >= 0:
                transformed_tokens.append(tokenize.TokenInfo(tokenize.NUMBER, f'0x{num:x}', token.start, token.end, token.line))
            else:
                transformed_tokens.append(tokenize.TokenInfo(tokenize.NUMBER, f'-0x{-num:x}', token.start, token.end, token.line))
        else:
            transformed_tokens.append(token)

    return tokenize.untokenize(transformed_tokens).decode('utf-8')

