def enhanced_split(path: str, delimiter: str = '/') -> tuple:
    if not path:
        return ("", "")

    # Convert the delimiter to a regular expression.
    import re
    delimiter_re = re.escape(delimiter)

    # Check if the path ends with the delimiter.
    if path.endswith(delimiter):
        path += '.'

    # Split the path using the last occurrence of the delimiter.
    parts = re.split(f"{delimiter_re}(.+)", path)

    # Return the appropriate part
    if len(parts) == 3:
        directory, filename = parts[1], parts[2]
    else:
        directory, filename = '', parts[1]

    return (directory, filename)
