def enhanced_split(path: str, delimiter: str = '/') -> tuple:
    """
    Splits the input path into two parts using the last occurrence of the specified delimiter.

    Args:
    path (str): The input file path.
    delimiter (str): The delimiter to split the path. Default is '/'.

    Returns:
    tuple: A tuple containing the directory path and the file name.
    """
    if not path:
        return ('', '')

    # Replace backslashes with the default delimiter
    path = path.replace('\\', delimiter)

    # Split the path using the last occurrence of the delimiter
    split_index = path.rfind(delimiter)

    if split_index == -1:
        # No delimiter found
        return ('', path)

    # Split the path into directory and file name
    directory = path[:split_index]
    file_name = path[split_index + 1:]

    return (directory, file_name)

