def run_length_encode(s):
    """
    Apply run-length encoding on the input string s.

    Parameters:
    - s: A string containing uppercase English letters.

    Returns:
    - A string representing the run-length encoded form of s.
    """
    if not s:
        return ""

    encoded = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            encoded.append(str(count) + s[i-1])
            count = 1

    # Append the last sequence
    encoded.append(str(count) + s[-1])

    return ''.join(encoded)

