def evaluate_postfix(expression: List[str]) -> int:
    stack = []
    for token in expression:
        if token.isdigit():
            stack.append(int(token))
        else:
            second = stack.pop()
            first = stack.pop()
            if token == '+':
                stack.append(first + second)
            elif token == '-':
                stack.append(first - second)
            elif token == '*':
                stack.append(first * second)
            elif token == '/':
                stack.append(int(first / second))  # Truncate towards zero
    return stack.pop()
