def find_minimum_bribes(queue):
    # Initialize the number of bribes
    bribes = 0

    # Loop through each person in the queue
    for i in range(len(queue)):
        # Check if the current person has bribed more than two others
        if queue[i] - (i + 1) > 2:
            return "Too chaotic"

        # Check the number of bribes for people in front of the current person
        for j in range(max(0, queue[i] - 2), i):
            if queue[j] > queue[i]:
                bribes += 1

    return bribes

