        return 0
    max_len = 0
    start = 0
    value_count = {}

    for end in range(len(nums)):
        if nums[end] not in value_count:
            value_count[nums[end]] = 0
        value_count[nums[end]] += 1

        while len(value_count) > 2:
            value_count[nums[start]] -= 1
            if value_count[nums[start]] == 0:
