def evaluate_revpol(expression):
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            stack.append(int(token))
        elif token in "+-*/^":
            if len(stack) < 2:
                return None
            right = stack.pop()
            left = stack.pop()
            if token == '+':
                stack.append(left + right)
            elif token == '-':
                stack.append(left - right)
            elif token == '*':
                stack.append(left * right)
            elif token == '/':
                stack.append(left // right)
            elif token == '^':
                stack.append(int(left ** right))  # Integer division
        else:
            return None

    if len(stack) == 1:
        return stack[0]
    else:
        return None
