class Solution:
    def evaluate_revpol(self, expression: str) -> int:
        # Split the expression by spaces to get the tokens
        tokens = expression.split()
        stack = []

        # Define a helper function to perform the division
        def divide(dividend, divisor):
            sign = -1 if (dividend < 0) ^ (divisor < 0) else 1
            dividend, divisor = abs(dividend), abs(divisor)
            quotient = 0
            sub = divisor
            while sub <= dividend:
                sub <<= 1
                mult = 1
            sub >>= 1
            mult >>= 1
            while sub > 0:
                if dividend >= sub:
                    dividend -= sub
                    quotient += mult
                sub >>= 1
                mult >>= 1
            return sign * quotient

        # Iterate over each token in the expression
        for token in tokens:
            if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
                # If the token is a number, push it onto the stack
                stack.append(int(token))
            elif token in "+-*/^":
                # If the token is an operator, pop the required number of operands from the stack
                if len(stack) < 2:
                    raise ValueError("Invalid expression")
                b = stack.pop()
                a = stack.pop()

                # Perform the operation based on the operator
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(divide(a, b))
                elif token == '^':
                    stack.append(a ** b)
            else:
                # If the token is invalid, raise an error
                raise ValueError("Invalid expression")

        # The final result should be the only element left in the stack
        if len(stack) != 1:
            raise ValueError("Invalid expression")

        return stack[0]
