import heapq

def trapRainWater(heightMap):
    if not heightMap or not heightMap[0]:
        return 0

    m, n = len(heightMap), len(heightMap[0])
    heap = []
    visited = [[False] * n for _ in range(m)]

    # Add all boundary cells to the heap
    for i in range(m):
        heapq.heappush(heap, (heightMap[i][0], i, 0))
        visited[i][0] = True
        heapq.heappush(heap, (heightMap[i][n-1], i, n-1))
        visited[i][n-1] = True
    for j in range(n):
        heapq.heappush(heap, (heightMap[0][j], 0, j))
        visited[0][j] = True
        heapq.heappush(heap, (heightMap[m-1][j], m-1, j))
        visited[m-1][j] = True

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    water_trapped = 0

    while heap:
        height, row, col = heapq.heappop(heap)
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < m and 0 <= new_col < n and not visited[new_row][new_col]:
                visited[new_row][new_col] = True
                new_height = heightMap[new_row][new_col]
                if new_height < height:
                    water_trapped += height - new_height
                    heapq.heappush(heap, (new_height, new_row, new_col))
                else:
                    heapq.heappush(heap, (new_height, new_row, new_col))

    return water_trapped
