    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        elif token == '+':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif token == '-':
            if len(stack) < 2:
