    right = [0] * n
    result = 0

    for i in range(1, n):
        if arr[i] > arr[i - 1]:
            left[i] = left[i - 1] + 1

    for i in range(n - 2, -1, -1):
        if arr[i] > arr[i + 1]:
            right[i] = right[i + 1] + 1

    for i in range(1, n - 1):
        if left[i] > 0 and right[i] > 0:
