def generateSubsets(arr, subsetSize=None):
    if subsetSize is None:
        subsetSize = len(arr)
    return _subsets_recursive(arr, [], 0, subsetSize)

def _subsets_recursive(arr, current, start, subsetSize):
    if len(current) == subsetSize:
        yield current
    elif start >= len(arr):
        return
    for i in range(start, len(arr)):
        yield from _subsets_recursive(arr, current + [arr[i]], i + 1, subsetSize)

