def reverse_words_in_string(input_string):
    # Reverse the entire string
    reversed_string = ""
    for char in input_string:
        reversed_string = char + reversed_string

    # Split the reversed string into words
    words = []
    word = ""
    for char in reversed_string:
        if char == " ":
            if word:
                words.append(word)
                word = ""
        else:
            word += char
    if word:
        words.append(word)

    # Reverse the order of words
    reversed_words = []
    for i in range(len(words) - 1, -1, -1):
        reversed_words.append(words[i])

    # Join the reversed words to form the final reversed string
    final_reversed_string = ""
    for word in reversed_words:
        final_reversed_string += word + " "
    return final_reversed_string.strip()

