from datetime import datetime

def convert_to_24_hour(time_str):
    try:
        # Check if the time string matches the 12-hour format
        if ':' not in time_str or len(time_str) != 8 or not time_str[5] == ' ':
            raise ValueError("Invalid time format. Expected format is 'HH:MM AM/PM'.")

        # Parse the time string
        hour, minute, period = time_str.split()

        # Validate hour
        if not hour.isdigit() or not 1 <= int(hour) <= 12:
            raise ValueError("Invalid hour. Hour must be between 1 and 12.")

        # Validate minute
        if not minute.isdigit() or not 0 <= int(minute) < 60:
            raise ValueError("Invalid minute. Minute must be between 0 and 59.")

        # Convert to 24-hour format
        if period == 'AM':
            if hour == '12':
                hour = '00'
            return f"{int(hour):02}:{minute}"
        elif period == 'PM':
            if hour != '12':
                hour = str(int(hour) + 12)
            return f"{hour}:{minute}"
        else:
            raise ValueError("Invalid period. Must be 'AM' or 'PM'.")
    except Exception as e:
        return str(e)

# Example usage
