from typing import List, Tuple
import copy

def reconstructQueue(heights: List[int], inFronts: List[int]) -> List[List[int]]:
    # Combine heights and inFronts into a tuple and sort by height in descending order
    people = [(h, i) for h, i in zip(heights, inFronts)]
    people.sort(reverse=True)

    # Initialize an empty list to hold the result
    queue = [None] * len(people)

    # Place each person in the queue according to their inFront value
    for person, i in people:
        # Find the correct position to insert the person
        while queue[i] is not None:
            i += 1
        # Insert the person at the found position
        queue[i] = [person, inFronts[heights.index(person)]]

    return queue

class Solution:
    def reconstructQueue(self, heights: List[int], inFronts: List[int]) -> List[List[int]]:
        return reconstructQueue(heights, inFronts)
