from typing import List

def find_pattern_occurrences(text: str, pattern: str) -> List[int]:
    # Implementation of Rabin-Karp algorithm
    def to_int(char: str) -> int:
        return ord(char) - ord('a')

    def hash_function(s: str) -> int:
        result = 0
        a_pow = 1
        for char in reversed(s):
            result += to_int(char) * a_pow
            a_pow *= 26
        return result

    def rabin_karp(text: str, pattern: str) -> List[int]:
        m, n = len(pattern), len(text)
        if m > n:
            return []

        pattern_hash = hash_function(pattern)
        text_hash = hash_function(text[:m])
        result = []

        a_pow = 26 ** (m - 1)

        for i in range(n - m + 1):
            if text_hash == pattern_hash:
                if text[i:i+m] == pattern:
                    result.append(i)

            if i + m < n:
                text_hash = 26 * (text_hash - to_int(text[i]) * a_pow) + to_int(text[i + m])

        return result

    return rabin_karp(text, pattern)

# Example usage
example_text = "abcabcdabc"
example_pattern = "abc"
result = find_pattern_occurrences(example_text, example_pattern)
print(result)  # Output: [0, 3, 7]
