def can_form_palindrome(s: str) -> bool:
    # Convert to lowercase and filter out non-alphanumeric characters
    filtered_chars = [char.lower() for char in s if char.isalnum()]

    # Count the occurrence of each character
    char_count = {}
    for char in filtered_chars:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check the number of characters with odd counts
    odd_count = sum(1 for count in char_count.values() if count % 2 != 0)

    # For the string to be rearrangeable into a palindrome, there can be at most one character with an odd count
    return odd_count <= 1
