def is_match(s: str, p: str) -> bool:
    """
    Determines if the given string s matches the pattern p.

    Parameters:
    s (str): The string to be matched.
    p (str): The pattern containing regex like '.' and '*'.

    Returns:
    bool: True if the string matches the pattern, False otherwise.
    """
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]

    # dp[i][j] will be True if the first i characters in s match the first j characters in p
    dp[0][0] = True  # Pattern and string empty

    # Handle patterns with '*' by checking empty string match
    for j in range(2, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] if p[j - 2] == '.' or p[j - 2] == s[i - 1] else False)

    return dp[len(s)][len(p)]

