from typing import Dict

def deep_merge_dicts(dict1: Dict, dict2: Dict) -> Dict:
    result = dict1.copy()  # Create a deep copy of dict1 to avoid modifying the original dictionary
    for key, value in dict2.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = deep_merge_dicts(result[key], value)  # Recursively merge sub-dictionaries
        else:
            result[key] = value  # Overwrite or add the key-value pair
    return result

