def is_valid_binary_tree(edges: List[Tuple[int, int]]) -> bool:
    nodes = {u for u, v in edges} | {v for u, v in edges}
    edges_dict = {u: [] for u in nodes}

    for u, v in edges:
        edges_dict[u].append(v)

    parent_count = {u: 0 for u in nodes}

    for u, vs in edges_dict.items():
        for v in vs:
            if parent_count[v] > 0:
                return False
            parent_count[v] += 1

    return sum(parent_count.values()) == len(nodes) - 1

