```python
import re

def transform_text(text):
    # Function to transform a single word based on its position
    def transform_word(word, position):
        if position % 2 == 0:
            return word.upper()
        else:
            return word.lower()

    # Split the text into words and punctuation using regex
    words_and_punct = re.findall(r'\b\w+\b|[^\w\s]', text, re.UNICODE)
    transformed_text = []

    word_index = 0
    for item in words_and_punct:
        if item.isalpha():
            # Transform the word
            transformed_word = transform_word(item, word_index)
            transformed_text.append(transformed_word)
            word_index += 1
        else:
            # Preserve punctuation and spaces
            transformed_text.append(item)

    # Reconstruct the transformed text
    return ''.join(transformed_text)

# Example usage:
