def find_unique_integer(nums):
    # 使用哈希表统计每个整数出现的次数
    num_dict = {}
    for num in nums:
        if num in num_dict:
            num_dict[num] += 1
        else:
            num_dict[num] = 1

    # 遍历哈希表，找到出现次数为1的整数
    for num, count in num_dict.items():
        if count == 1:
            return num
