def is_match(str_a: str, str_b: str) -> bool:
    @lru_cache(None)
    def dp(s_idx: int, p_idx: int) -> bool:
        if p_idx == len(str_b):
            return s_idx == len(str_a)
        first_match = s_idx < len(str_a) and (str_a[s_idx] == str_b[p_idx] or str_b[p_idx] == '.')
        if p_idx + 1 < len(str_b) and str_b[p_idx + 1] == '*':
            return dp(s_idx, p_idx + 2) or (first_match and dp(s_idx + 1, p_idx))
        return first_match and dp(s_idx + 1, p_idx + 1)

    return dp(0, 0)
```

