def is_match(str_a: str, str_b: str) -> bool:
    # Base case: if both strings are empty, they match
    if not str_b:
        return not str_a

    # Check if the first character of the pattern matches the first character of the string
    first_match = bool(str_a) and str_a[0] == str_b[0] or str_b[0] == '.'

    # If the pattern has a '*', it can match zero or more characters of the string
    if len(str_b) >= 2 and str_b[1] == '*':
        # Option 1: '*' matches zero occurrence of the preceding element
        # Option 2: '*' matches one or more occurrences of the preceding element if there's a match
        return is_match(str_a, str_b[2:]) or (first_match and is_match(str_a[1:], str_b))

    # If the pattern doesn't have '*', just move to the next character in both string and pattern
    return first_match and is_match(str_a[1:], str_b[1:])
```

