import heapq

def min_steps_to_bottom_right(grid):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    heap = [(0, 0, 0)]  # (steps, x, y)
    visited = set()

    while heap:
        steps, x, y = heapq.heappop(heap)

        if (x, y) in visited:
            continue

        visited.add((x, y))

        if x == rows - 1 and y == cols - 1:
            return steps

