def unique_string_permutations(s: str, max_length: int) -> list:
    result = set()
    def permute(data, s, left, right):
        if left == right and len(data) <= max_length:
            result.add(''.join(data[:]))
        else:
            for i in range(left, right + 1):
                data[left], data[i] = data[i], data[left]
                permute(data, s, left + 1, right)
                data[left], data[i] = data[i], data[left]  # backtracking

    data = list(s)
    permute(data, s, 0, len(s) - 1)
    return sorted(list(result))
