def unique_string_permutations(s: str, max_length: int) -> list:
    def backtrack(s, path, used):
        if len(path) == max_length:
            result.add(path)
            return
        for i in range(len(s)):
            if i > 0 and s[i] == s[i - 1] and not used[i - 1]:
                continue
            if not used[i]:
                used[i] = True
                backtrack(s, path + s[i], used)
                used[i] = False

    if max_length == 0:
        return []

    result = set()
    used = [False] * len(s)
    s = sorted(s)
    backtrack(s, "", used)
    return sorted(result)
