def find_two_sum_pairs(nums: List[int], target: int) -> List[Tuple[int, int]]:
    hash_map = {}
    pairs = set()

    for i, num in enumerate(nums):
        complement = target - num
        if complement in hash_map:
            if (hash_map[complement], i) not in pairs:
                pairs.add((hash_map[complement], i))
            if (i, hash_map[complement]) not in pairs:
                pairs.add((i, hash_map[complement]))
        hash_map[num] = i

    return sorted(pairs)
