def prefix_sum_2d_array(array):
    rows = len(array)
    cols = len(array[0])
    prefix_sum = [[0]*cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            prefix_sum[i][j] = array[i][j]
            if i > 0:
                prefix_sum[i][j] += prefix_sum[i-1][j]
            if j > 0:
                prefix_sum[i][j] += prefix_sum[i][j-1]
            if i > 0 and j > 0:
                prefix_sum[i][j] -= prefix_sum[i-1][j-1]

    return prefix_sum
