def classify_sequence(sequence: list) -> str:
    # Check for the length of the list to handle edge cases
    if len(sequence) < 2:
        return None

    # Calculate the difference and ratio for the first two elements
    difference = sequence[1] - sequence[0]
    if difference == 0:
        return None  # Avoid division by zero if the sequence has a zero difference

    ratio = sequence[1] / sequence[0]

    # Check if the rest of the sequence maintains the same difference or ratio
    for i in range(2, len(sequence)):
        if sequence[i] - sequence[i-1] != difference:
            if sequence[i] / sequence[i-1] != ratio:
                return None

    # Determine the type of sequence
    if difference == 0:
        return "Arithmetic"
    if all(abs(sequence[i] / sequence[i-1] - ratio) < 1e-9 for i in range(2, len(sequence))):
        return "Geometric"

    # If neither condition is met, it's not a clear geometric sequence
    return None
