def maxOccurrence(S):
    # Create a dictionary to store the count of each character
    char_count = {}

    # Iterate over each character in the string
    for char in S:
        if char in char_count:
            # If the character is already in the dictionary, increment its count
            char_count[char] += 1
        else:
            # If the character is not in the dictionary, add it with a count of 1
            char_count[char] = 1

    # Initialize variables to keep track of the maximum count and the corresponding character
    max_count = 0
    max_char = ''

    # Iterate over each character and its count in the dictionary
    for char, count in char_count.items():
        # If the current count is greater than max_count, update max_count and max_char
        if count > max_count:
            max_count = count
            max_char = char
        # If the current count is equal to max_count, choose the lexicographically smaller character
        elif count == max_count and char < max_char:
            max_char = char

    # Return the character with the maximum count
    return max_char
