def hardy_ramanujan(n):
    """
    Checks if a number can be expressed as the sum of two cubes in two different ways.

    Args:
        n: An integer.

    Returns:
        True if the number can be expressed as the sum of two cubes in two different ways, 
        and False otherwise.
    """
    cube_dict = {}
    for i in range(int(n**(1/3)) + 1):
        for j in range(i, int(n**(1/3)) + 1):
            cube = i**3 + j**3
            if cube > n:
                break
            if cube in cube_dict:
                cube_dict[cube].append((i, j))
            else:
                cube_dict[cube] = [(i, j)]

    pairs = cube_dict.get(n, [])
