def hardy_ramanujan(n):
    """
    Checks if a number can be expressed as the sum of two cubes in two different ways.

    Args:
        n: An integer.

    Returns:
        True if the number can be expressed as the sum of two cubes in two different ways, 
        and False otherwise.
    """
    cubes = {}
    for i in range(1, int(n**(1/3)) + 1):
        cubes[i**3] = i

    for i in cubes:
        for j in cubes:
            if i <= j and (i + j == n):
                if (i in cubes and j in cubes) and (cubes[i] != cubes[j]):
                    return True
    return False
