def can_form_palindrome(s: str) -> bool:
    # Create a dictionary to count occurrences of each character
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Count characters with odd occurrences
    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    # A string can form a palindrome if there is at most one character with an odd count
    return odd_count <= 1

