def reorderToPalindrome(s):
    # To form a palindrome, at most one character can have an odd count.
    # All other characters must have even counts.
    char_count = {}
    odd_count_chars = 0

    # Count the occurrences of each character, ignoring case.
    for char in s.lower():
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Count how many characters have an odd number of occurrences.
    for count in char_count.values():
        if count % 2 != 0:
            odd_count_chars += 1

    # If more than one character has an odd count, it's not possible to form a palindrome.
    return odd_count_chars <= 1
