def longest_substring_with_n_distinct_chars(n, s):
    char_map = {}
    start = 0
    max_length = 0
    max_substring = ""

    for end in range(len(s)):
        if s[end] in char_map:
            char_map[s[end]] += 1
        else:
            char_map[s[end]] = 1

        while len(char_map) > n:
            char_map[s[start]] -= 1
            if char_map[s[start]] == 0:
                del char_map[s[start]]
            start += 1

        if end - start + 1 > max_length:
            max_length = end - start + 1
            max_substring = s[start:end+1]

