# functions

def read_file(filename):
    try:
        with open(filename, 'r') as file:
            return file.read()
    except FileNotFoundError:
        return ""

def remove_stop_words(text, stop_words):
    return ' '.join(word for word in text.split() if word.lower() not in stop_words)

def count_word_frequencies(text):
    words = text.split()
    freq_dict = {}
    for word in words:
        word = word.lower()
        if word in freq_dict:
            freq_dict[word] += 1
        else:
            freq_dict[word] = 1
    return freq_dict

def sort_frequencies(freq_dict):
    return dict(sorted(freq_dict.items(), key=lambda item: item[1], reverse=True))

def main(filename):
    text = read_file(filename)
    if not text:
        print("File is empty or not found.")
        return
    stop_words = ['and', 'the', 'is', 'in', 'at', 'on', 'to', 'for', 'with', 'of']
    text_without_stop_words = remove_stop_words(text, stop_words)
    word_frequencies = count_word_frequencies(text_without_stop_words)
    sorted_word_frequencies = sort_frequencies(word_frequencies)
    print(sorted_word_frequencies)

if __name__ == "__main__":
    filename = "example.txt"
    main(filename)
