def evaluate_postfix_expression(expression: str) -> int:
    # Split the expression into tokens based on spaces
    tokens = expression.split()
    # Initialize an empty stack
    stack = []

    # Iterate through each token in the postfix expression
    for token in tokens:
        # If the token is an operand, push it onto the stack
        if token.isdigit():
            stack.append(int(token))
        # If the token is an operator, pop the required operands from the stack,
        # apply the operator, and push the result back onto the stack
        else:
            # Pop the second operand
            b = stack.pop()
            # Pop the first operand
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a // b)

    # The final result is the only element left in the stack
    return stack.pop()

