    '2': [ [3, '1'], [5, '4'] ],
    '3': [ [8, '1'], [2, '4'], [4, '5'] ],
    '4': [ [5, '2'], [2, '3'], [6, '5'] ],
    '5': [ [4, '3'], [6, '4'] ]
}

assert prims_minimum_spanning(graph) == 14
