class Solution:
    def longestMountain(self, A):
        n = len(A)
        longest_mountain = 0
        i = 0
        while i < n:
            j = i
            if j + 1 < n and A[j] < A[j + 1]:
                # Strictly increasing phase
                while j + 1 < n and A[j] < A[j + 1]:
                    j += 1
                # Check for strictly decreasing phase
                if j + 1 < n and A[j] > A[j + 1]:
                    while j + 1 < n and A[j] > A[j + 1]:
                        j += 1
                    # Update longest mountain length
                    longest_mountain = max(longest_mountain, j - i + 1)
            # Move to the next element
            i = max(i + 1, j)
        return longest_mountain
