def longestMountain(nums):
    if not nums:
        return 0

    n = len(nums)
    left = [0] * n
    right = [0] * n
    result = 0

    # Calculate left mountains
    for i in range(1, n):
        if nums[i] > nums[i-1]:
            left[i] = left[i-1] + 1

    # Calculate right mountains
    for i in range(n-2, -1, -1):
        if nums[i] > nums[i+1]:
            right[i] = right[i+1] + 1

    # Find the longest mountain
    for i in range(1, n-1):
        if left[i] > 0 and right[i] > 0:
            result = max(result, left[i] + right[i] + 1)

    return result if result > 2 else 0

