def most_frequent_smallest(nums: list) -> int:
    if not nums:
        return None  # Edge case handling, though the problem specifies that the list will always have at least one element.

    # Dictionary to store the frequency of each number
    frequency = {}
    for num in nums:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    # Find the most frequent number and the smallest one among them
    max_count = 0
    result = float('inf')
    for num, count in frequency.items():
        if count > max_count or (count == max_count and num < result):
            max_count = count
            result = num

    return result

