def longestMountain(nums):
    n = len(nums)
    left = [0] * n
    right = [0] * n

    # Calculate the length of the strictly increasing sequence to the left of each element
    for i in range(1, n):
        if nums[i] > nums[i - 1]:
            left[i] = left[i - 1] + 1

    # Calculate the length of the strictly decreasing sequence to the right of each element
    for i in range(n - 2, -1, -1):
        if nums[i] > nums[i + 1]:
            right[i] = right[i + 1] + 1

    max_length = 0

    # Find the longest mountain
    for i in range(n):
        if left[i] > 0 and right[i] > 0:
            max_length = max(max_length, left[i] + right[i] + 1)

    return max_length

