import math
from typing import Tuple

def shortest_distance(point: Tuple[float, float], segment_start: Tuple[float, float], segment_end: Tuple[float, float]) -> float:
    def dot(v1: Tuple[float, float], v2: Tuple[float, float]) -> float:
        return v1[0] * v2[0] + v1[1] * v2[1]

    def subtract(v1: Tuple[float, float], v2: Tuple[float, float]) -> Tuple[float, float]:
        return (v1[0] - v2[0], v1[1] - v2[1])

    def add(v1: Tuple[float, float], v2: Tuple[float, float]) -> Tuple[float, float]:
        return (v1[0] + v2[0], v1[1] + v2[1])

    def length(v: Tuple[float, float]) -> float:
        return math.sqrt(v[0] ** 2 + v[1] ** 2)

    def normalize(v: Tuple[float, float]) -> Tuple[float, float]:
        l = length(v)
        return (v[0] / l, v[1] / l)

    p, p1, p2 = point, segment_start, segment_end
    v1 = subtract(p2, p1)
    v2 = subtract(p, p1)
    dot_product = dot(v1, v2)
    segment_length_squared = dot_product ** 2 / length(v1) ** 2

    closest_point_on_segment = add(p1, (v1[0] * segment_length_squared, v1[1] * segment_length_squared))

    # Clamp the closest point to the segment
    clamped_point = (
        max(min(closest_point_on_segment[0], p2[0]), p1[0]),
        max(min(closest_point_on_segment[1], p2[1]), p1[1])
    )

    return length(subtract(clamped_point, p))
