def run_tests():
    tests = [
        {"input": {"n": 10}, "expected": [2, 3, 5, 7]},
        {"input": {"n": 2}, "expected": [2]},
        {"input": {"n": 5}, "expected": [2, 3, 5]},
        {"input": {"n": 0}, "expected": []},
        {"input": {"n": 1}, "expected": []},
        {"input": {"n": 20}, "expected": [2, 3, 5, 7, 11, 13, 17, 19]},
        {"input": {"n": 18}, "expected": [2, 3, 5, 7, 11, 13, 17]}
    ]

    for test in tests:
        result = sieve_of_eratosthenes(test["input"]["n"])
        if result != test["expected"]:
            return {"status": "fail", "error": f"Test failed for input {test['input']['n']}. Expected {test['expected']}, got {result}"}

    return {"status": "pass", "message": "All tests passed successfully."}

def sieve_of_eratosthenes(n):
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False

    return [i for i in range(n + 1) if is_prime[i]]
