def can_form_palindrome(s):
    letter_count = {}
    for char in s:
        if char in letter_count:
            letter_count[char] += 1
        else:
            letter_count[char] = 1
    odd_letters = 0
    for count in letter_count.values():
        if count % 2 != 0:
            odd_letters += 1
    return odd_letters <= 1
