            if num - left in index_map:
                count += len(index_map[num - left])
        # 检查右侧k范围内的数字
        for right in range(1, k + 1):
            if num + right in index_map:
                count += len(index_map[num + right])
        # 如果数字在index_map中但没有朋友，设置为1
