import bisect
from typing import List

def count_duos(words: List[str], k: int) -> int:
    duos = 0
    words.sort()
    for word in words:
        prefix = word[:k]
        start = bisect.bisect_left(words, prefix)
        end = bisect.bisectRight(words, prefix)
        if end > start and end <= len(words):
            for i in range(start, end):
                if words[i][:k] == prefix and words[i] != word:
                    duos += 1
    return duos // 2

