def combination_dp(n: int, r: int) -> int:
    # Initialize a 2D array to store intermediate results
    dp = [[0 for _ in range(r+1)] for _ in range(n+1)]

    # Fill the dp array using bottom-up approach
    for i in range(n+1):
        for j in range(min(i, r)+1):
            if j == 0 or j == i:
                dp[i][j] = 1
            else:
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j]

