def next_bigger(num: int) -> int:
    # Convert the number to a list of its digits
    digits = list(str(num))

    # Start from the second last digit and move backwards
    for i in range(len(digits) - 2, -1, -1):
        # If the current digit is less than the digit next to it
        if digits[i] < digits[i + 1]:
            # Find the smallest digit on the right side of (i'th digit) that is greater than digits[i]
            for j in range(len(digits) - 1, i, -1):
                if digits[j] > digits[i]:
                    # Swap the found digit with digits[i]
                    digits[i], digits[j] = digits[j], digits[i]
                    # Sort the digits after the (i'th digit) in ascending order
                    digits[i + 1:] = sorted(digits[i + 1:])
                    # Return the new permutation
                    return int("".join(digits))
    # If no bigger permutation is possible
    return -1
