Let's implement the Rabin-Karp algorithm to find the first occurrence of a pattern in a text. We'll use a rolling hash to efficiently compute the hash of substrings and compare them with the hash of the pattern.

First, let's define the rolling hash class and the Rabin-Karp function.

```python
class RollingHash:
    def __init__(self, text, base=256, prime=1000000007):
        self.text = text
        self.n = len(text)
        self.base = base
        self.prime = prime
        self.pow = [1] * (self.n + 1)
        self.hash = [0] * (self.n + 1)

        for i in range(1, self.n + 1):
            self.pow[i] = (self.pow[i - 1] * self.base) % self.prime
            self.hash[i] = (self.hash[i - 1] * self.base + ord(self.text[i - 1])) % self.prime

    def get_hash(self, start, end):
        return (self.hash[end] - self.hash[start] * self.pow[end - start]) % self.prime

def find_pattern(pattern: str, text: str) -> int:
    m = len(pattern)
    n = len(text)

    if m > n:
        return -1

    pattern_hash = 0
    text_hash = 0
    base = 256
    prime = 1000000007

    # Calculate the hash of the pattern and the first window of the text
    for i in range(m):
        pattern_hash = (pattern_hash * base + ord(pattern[i])) % prime
        text_hash = (text_hash * base + ord(text[i])) % prime

    # Check if the first window matches the pattern
    if pattern_hash == text_hash:
        return 0

    # Calculate the hash values for the remaining windows
    for i in range(m, n):
        text_hash = (text_hash * base - ord(text[i - m]) * base + ord(text[i])) % prime
        if text_hash < 0:
            text_hash += prime

        if pattern_hash == text_hash:
            return i - m + 1

    return -1
```

