class RollingHash:
    def __init__(self, text, pattern):
        self.text = text
        self.pattern = pattern
        self.pattern_length = len(pattern)
        self.text_length = len(text)
        self.p = 31
        self.m = 2**64  # A large prime number to reduce hash collisions
        self.h_pattern = 0
        self.h_text = 0
        self.p_pow = [0] * (self.pattern_length + 1)

        # Precompute powers of p
        for i in range(self.pattern_length):
            self.p_pow[i] = (self.p_pow[i - 1] * self.p) % self.m

        # Compute hash values for the pattern and the first window of the text
        for i in range(self.pattern_length):
            self.h_pattern = (self.h_pattern * self.p + ord(self.pattern[i]) - ord('a')) % self.m
            self.h_text = (self.h_text * self.p + ord(self.text[i]) - ord('a')) % self.m

    def roll(self, old_index):
        # Remove old character's hash and add new character's hash
        new_index = old_index + self.pattern_length
        self.h_text = ((self.h_text * self.p - ord(self.text[old_index]) * self.p_pow[self.pattern_length - 1]) % self.m + ord(self.text[new_index]) - ord('a')) % self.m

        # Ensure non-negative hash
        if self.h_text < 0:
            self.h_text += self.m

        return new_index

    def compare(self):
        # If hash values match, compare strings to handle hash collisions
        if self.h_pattern == self.h_text:
            for i in range(self.pattern_length):
                if self.pattern[i] != self.text[i]:
                    return False
            return True
        return False

def find_pattern(pattern: str, text: str) -> int:
    if not pattern or not text or len(pattern) > len(text):
        return -1

    rh = RollingHash(text, pattern)

    for i in range(len(text) - len(pattern) + 1):
        if rh.compare():
            return i
        if i + len(pattern) < len(text):
            rh.roll(i)

    return -1
```

