def min_repeats(A: str, B: str) -> int:
    """
    Find the minimum number of times string A must be repeated to contain string B as a substring.

    Args:
    A (str): The base string to be repeated.
    B (str): The string to check for as a substring.

    Returns:
    int: The minimum number of repetitions required, or -1 if B cannot be a substring of any repeated A.
    """
    # Double the string A to account for cases where B could wrap around.
    doubled_A = A + A

    # Use the Knuth-Morris-Pratt (KMP) algorithm to find B in the doubled string A.
    # This efficiently checks for repeated and continuous occurrence of B within A.
    n, m = len(doubled_A), len(B)
    lps = [0] * n
    j = 0
    for i in range(1, n):
        while j > 0 and doubled_A[i] != doubled_A[j]:
            j = lps[j - 1]
        if doubled_A[i] == doubled_A[j]:
            j += 1
        lps[i] = j
    i = j = 0
    while i < n:
        if doubled_A[i] == B[j]:
            i += 1
            j += 1
            if j == m:
                return (i - m) // len(A) + 1  # Calculate the number of repetitions
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return -1  # B cannot be a substring of any repeated A

