def find_primes_interval(start: int, end: int) -> list[int]:
    if start < 2:
        start = 2
    primes = []

    # Generate a list of boolean values to mark prime numbers
    is_prime = [True] * (end + 1)
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not prime numbers

    # Apply the Sieve of Eratosthenes
    for number in range(2, int(end ** 0.5) + 1):
        if is_prime[number]:
            for multiple in range(number * number, end + 1, number):
                is_prime[multiple] = False

    # Collect all prime numbers in the given range
    for num in range(start, end + 1):
        if is_prime[num]:
            primes.append(num)

    return primes

