class Solution:
    def longestOverlap(self, timeSeries1: List[int], timeSeries2: List[int]) -> int:
        max_overlap = 0
        i = j = 0
        while i < len(timeSeries1) and j < len(timeSeries2):
            if timeSeries1[i] > timeSeries2[j]:
                j += 1
            elif timeSeries1[i] < timeSeries2[j]:
                i += 1
            else:
                start = timeSeries1[i]
                while i < len(timeSeries1) and timeSeries1[i] == start:
                    i += 1
                while j < len(timeSeries2) and timeSeries2[j] == start:
                    j += 1
                max_overlap = max(max_overlap, i - j)
        return max_overlap

