def min_split_cost(arr):
    n = len(arr)
    dp = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = arr[i]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            for k in range(i, j):
                dp[i][j] = min(dp[i][j], max(dp[i][k], dp[k + 1][j]) - min(dp[i][k], dp[k + 1][j]))
    return dp[0][n - 1]

