def rearrange_string(input_str: str) -> str:
    letters = []
    digits = []
    # 遍历输入字符串，将字母和数字分别添加到对应的列表中
    for char in input_str:
        if char.isalpha():
            letters.append(char)
        elif char.isdigit():
            digits.append(char)
    # 将字母和数字列表合并得到结果字符串
    return ''.join(letters + digits)
